import 'package:flutter/material.dart';import 'package:flutter_screenutil/flutter_screenutil.dart';import '../../../../Core/Resources/app_icons.dart';import '../../../../Core/Utils/Extensions/context_extension.dart';import '../../../../Core/Utils/Extensions/localizations_extension.dart';import '../../../../Core/Resources/app_colors.dart';import '../../../../Core/Resources/app_fonts.dart';import 'build_item_setting.dart';import 'language_selector.dart';class BuildBodySetting extends StatelessWidget {  const BuildBodySetting({    super.key,  });  @override  Widget build(BuildContext context) {    return SliverFillRemaining(      fillOverscroll: true,      hasScrollBody: false,      child: Column(        crossAxisAlignment: CrossAxisAlignment.start,        children: [          _buildSetting(context),          BuildItemSetting(            title: context.local.YourCard,            icon: AppIcons.card,            onTap: () {},          ),          BuildItemSetting(            title: context.local.Security,            icon: AppIcons.shield,            onTap: () {},          ),          BuildItemSetting(            title: context.local.Notifications,            icon: AppIcons.notificationWithoutBackGround,            onTap: () {},          ),          BuildItemSetting(            title: context.local.Languages,            icon: AppIcons.globe,            onTap: () {              context.buildCustomBottomSheet(                widget: LanguageList(),              );            },          ),          BuildItemSetting(            title: context.local.Info,            icon: AppIcons.circleInfo,            onTap: () {},          ),        ],      ),    );  }  Padding _buildSetting(BuildContext context) => Padding(        padding: const EdgeInsets.symmetric(vertical: 24).r,        child: Text(          context.local.Setting,          style: AppTextStyles.h7Bold.copyWith(            color: AppColors.grayscale60,          ),        ),      );}